---
{
  "name": "dbms-family",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "wrangler dev --port 8788",
    "deploy": "wrangler deploy",
    "db:migrate": "wrangler d1 migrations apply dbms --local",
    "db:migrate:remote": "wrangler d1 migrations apply dbms --remote",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "hono": "^4.6.0"
  },
  "devDependencies": {
    "@cloudflare/workers-types": "^5.20260820.1",
    "typescript": "^5.6.0",
    "wrangler": "^4.25.0"
  },
  "engines": {
    "node": ">=18"
  }
}

{
  "$schema": "node_modules/wrangler/config-schema.json",
  "name": "dbms-family",
  "main": "src/index.ts",
  "compatibility_date": "2026-08-01",
  "d1_databases": [
    {
      "binding": "DB",
      "database_name": "dbms",
      // placeholder id; real id assigned on first `wrangler d1 create` for remote deploys
      "database_id": "00000000-0000-0000-0000-000000000000"
    }
  ],
  "vars": {
    "B2_ENDPOINT": "https://s3.us-west-004.backblazeb2.com",
    "B2_BUCKET": "dbms-family-photos"
  }
}
---
