```js
'use strict';
/* ---------- tiny DOM helpers ---------- */
const $ = (sel, root=document)=>root.querySelector(sel);
const $$ = (sel, root=document)=>[...root.querySelectorAll(sel)];
function esc(s){ return String(s??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

/* ---------- state ---------- */
const state = { me:null, meReady:false };

/* ---------- api ---------- */
class ApiError extends Error{ constructor(status, message){ super(message); this.status=status; } }
async function api(method, path, body){
  const opts={method, credentials:'same-origin', headers:{}};
  if(body!==undefined){ opts.headers['Content-Type']='application/json'; opts.body=JSON.stringify(body); }
  let res;
  try{ res=await fetch(path,opts); } catch(e){ throw new ApiError(0,'Network error — check your connection.'); }
  let data=null;
  const ct=res.headers.get('content-type')||'';
  if(ct.includes('application/json')){ try{ data=await res.json(); }catch{} }
  if(!res.ok){ throw new ApiError(res.status, (data&&data.error)||('Request failed ('+res.status+')')); }
  return data;
}

async function ensureMe(){ if(state.meReady) return state.me; try{ state.me = await api('GET','/api/me'); }catch(e){ state.me=null; } state.meReady=true; return state.me; }
```

