function drawLinks(){
  const canvas=$('#treeCanvas'), inner=$('#bandsInner'), svg=$('#linksSvg');
  if(!canvas||!inner||!svg) return;
  const w=inner.scrollWidth, h=inner.scrollHeight;
  svg.setAttribute('viewBox',`0 0 ${w} ${h}`);
  svg.setAttribute('width',w); svg.setAttribute('height',h);
  const ib=inner.getBoundingClientRect();
  const bands=$$('.band',inner);
  let paths='';
  for(let i=1;i<bands.length;i++){
    const ups=$$('.couple-card',bands[i-1]);
    const downs=$$('.couple-card',bands[i]);
    if(!ups.length||!downs.length) continue;
    const centers=ups.map(u=>{const r=u.getBoundingClientRect();return {x:r.left+r.width/2-ib.left, y:r.bottom-ib.top};});
    const groups=new Map();
    downs.forEach(d=>{ const r=d.getBoundingClientRect(); const cx=r.left+r.width/2-ib.left;
      let bi=0,bd=Infinity; centers.forEach((c,idx)=>{const dist=Math.abs(c.x-cx); if(dist<bd){bd=dist;bi=idx;}});
      if(!groups.has(bi)) groups.set(bi,[]); groups.get(bi).push({x:cx,y:r.top-ib.top});
    });
    groups.forEach((kids,ui)=>{
      const p=centers[ui];
      const busY=p.y+(kids.reduce((s,k)=>s+k.y,0)/kids.length - p.y)*0.5; // midway
      paths+=`<path d="M ${p.x} ${p.y} L ${p.x} ${busY}" />`; // trunk
      kids.forEach(k=>{ paths+=`<path d="M ${p.x} ${busY} L ${k.x} ${busY} L ${k.x} ${k.y}" />`; });
    });
  }
  svg.innerHTML=paths;
}
```

