'use strict';

/* ================= utilities ================= */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

const ESC_MAP = { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' };
function esc(v){ return String(v == null ? '' : v).replace(/[&<>"']/g, ch => ESC_MAP[ch]); }

function fmtDate(iso){
  if(!iso) return '';
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso));
  if(!m) return String(iso);
  const months=['January',...];
  return `${Number(m[3])} ${months[Number(m[2])-1]} ${m[1]}`;
}
function withUnit(v, unit){ const s=String(v==null?'':v).trim(); if(!s) return ''; return /^\d+(\.\d+)?$/.test(s) ? s+' '+unit : s; }
function initials(name){ const parts=String(name||'').trim().split(/\s+/).filter(Boolean); return ((parts[0]||'')[0]||'?').toUpperCase() + ((parts[1]||'')[0]||'').toUpperCase(); }
function snippet(s,n=110){ s=String(s==null?'':s).replace(/\s+/g,' ').trim(); return s.length>n? s.slice(0,n-1)+'…' : s; }
function roman(n){ const R=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII']; return R[n-1]||String(n); }

/* ================= state & api ================= */
