```js
async function route(){
  closeModal();
  const r=parseHash();
  if(r.name==='home'){ nav(state.me? '#/trees':'#/login'); return; }
  if(r.name==='login'){
    if(!(await ensureMe())) { renderLogin(); return; }
    nav('#/trees'); return;
  }
  // protected
  if(!(await ensureMe())){ nav('#/login'); return; }
  if(r.name==='trees') return renderTrees();
  if(r.name==='tree') return renderTree(r.id);
}
```

