```js
function drawLinks(){
  const inner=document.getElementById('bandsInner');
  const svg=document.getElementById('linksSvg');
  if(!inner||!svg) return;
  const w=inner.scrollWidth,h=inner.scrollHeight;
  if(!w||!h) return;
  svg.setAttribute('viewBox','0 0 '+w+' '+h);
  svg.setAttribute('width',String(w));
  svg.setAttribute('height',String(h));
  const ib=inner.getBoundingClientRect();
  const bands=$$('.band',inner);
  let out='';
  for(let i=1;i<bands.length;i++){
    const ups=$$('.couple-card',bands[i-1]);
    const lows=$$('.couple-card',bands[i]);
    if(!ups.length||!lows.length) continue;
    const heads=ups.map(u=>{
      const r=u.getBoundingClientRect();
      return {x:r.left+r.width/2-ib.left,y:r.bottom-ib.top};
    });
    const groups=new Map();
    lows.forEach(d=>{
      const r=d.getBoundingClientRect();
      const cx=r.left+r.width/2-ib.left;
      let best=0,bd=Infinity;
      heads.forEach((hd,idx)=>{const dist=Math.abs(hd.x-cx);if(dist<bd){bd=dist;best=idx;}});
      if(!groups.has(best))groups.set(best,[]);
      groups.get(best).push(cx? {x:cx,y:r.top-ib.top}:{x:cx,y:r.top-ib.top});
    });
    groups.forEach((targets,hi)=>{
      const hd=heads[hi];
      const ys=targets.map(t=>t.y);
      const busY=hd.y+(ys.reduce((s,v)=>s+v,0)/ys.length-hd.y)/2;
      out+='<circle class="joint" cx="'+hd.x+'" cy="'+hd.y+'" r="3"/>';
      out+='<path class="strand" d="M'+hd.x+' '+hd.y+' V'+busY+'"/>';
      targets.forEach(t=>{
        out+='<path class="strand" d="M'+hd.x+' '+busY+' H'+t.x+' V'+t.y+'"/>';
        out+='<circle class="joint joint-in" cx="'+t.x+'" cy="'+t.y+'" r="3"/>';
      });
    });
  }
  svg.innerHTML=out;
}
```

